package com.bananalab.lite;
import java.util.*;import java.util.regex.*;import org.json.*;
/** Bounded behavior language, interpreted locally. No Java, reflection, network, files or eval. */
final class RuntimeProgram{
 static final int MAX_BYTES=32768,MAX_MODULES=16,MAX_STEPS=8;final JSONObject source;final List<Module> modules=new ArrayList<>();
 static final Set<String> OPS=new HashSet<>(Arrays.asList("salta","baila","saluda","camina","gira","aplaude","espera","besa","mira","acercaactor"));
 static final class Module{JSONObject source;String id,pattern;Pattern compiled;List<String> groups=new ArrayList<>();JSONArray steps,tests;}
 static final class Match{Module module;Map<String,String> values=new HashMap<>();}
 static final class Result{boolean matched;String error="",module="";SceneDraft scene;}
 static void keys(JSONObject o,String...allowed)throws Exception{Set<String> set=new HashSet<>(Arrays.asList(allowed));Iterator<String> keys=o.keys();while(keys.hasNext()){String key=keys.next();if(!set.contains(key))throw new IllegalArgumentException("Campo no admitido: "+key);}}
 static String normalize(String s){return ChatLanguage.normalize(s).replaceAll("\\bal\\b","a el");}
 static String patternText(String s){return normalize(s.replace("{actor}","zzactorzz").replace("{target}","zztargetzz"));}
 RuntimeProgram(String raw)throws Exception{if(raw.getBytes("UTF-8").length>MAX_BYTES)throw new IllegalArgumentException("El código supera 32 KiB.");source=new JSONObject(raw);keys(source,"version","modules");if(source.optInt("version")!=1)throw new IllegalArgumentException("Versión del lenguaje no admitida.");JSONArray list=source.getJSONArray("modules");if(list.length()>MAX_MODULES)throw new IllegalArgumentException("El taller admite dieciséis módulos.");Set<String> ids=new HashSet<>(),patterns=new HashSet<>();for(int i=0;i<list.length();i++){JSONObject row=list.getJSONObject(i);keys(row,"id","pattern","steps","tests");Module m=new Module();m.source=row;m.id=row.getString("id");m.pattern=row.getString("pattern");if(!m.id.matches("[a-z][a-z0-9_]{1,31}")||!ids.add(m.id))throw new IllegalArgumentException("Identificador inválido o duplicado.");if(m.pattern.length()>140||!m.pattern.startsWith("{actor} ")||m.pattern.contains("\n"))throw new IllegalArgumentException("El patrón debe comenzar con {actor} y tener hasta140 caracteres.");String normalized=patternText(m.pattern);if(!patterns.add(normalized))throw new IllegalArgumentException("Hay patrones duplicados.");Matcher tokens=Pattern.compile("zzactorzz|zztargetzz").matcher(normalized);StringBuilder expression=new StringBuilder("^");int start=0;while(tokens.find()){String key=tokens.group().equals("zzactorzz")?"actor":"target";if(m.groups.contains(key))throw new IllegalArgumentException("Cada parámetro debe aparecer una vez.");expression.append(Pattern.quote(normalized.substring(start,tokens.start()))).append("(.{1,80}?)");m.groups.add(key);start=tokens.end();}expression.append(Pattern.quote(normalized.substring(start))).append('$');String literal=normalized.replace("zzactorzz","").replace("zztargetzz","").trim();if(!m.groups.contains("actor")||literal.length()<5||m.pattern.replace("{actor}","").replace("{target}","").matches("(?s).*[{}].*"))throw new IllegalArgumentException("Patrón sin verbo concreto o con parámetros desconocidos.");m.compiled=Pattern.compile(expression.toString());m.steps=row.getJSONArray("steps");if(m.steps.length()<1||m.steps.length()>MAX_STEPS)throw new IllegalArgumentException("Cada módulo admite de uno a ocho pasos.");for(int j=0;j<m.steps.length();j++){JSONObject step=m.steps.getJSONObject(j);keys(step,"op","who","to");String op=step.getString("op"),who=step.getString("who"),to=step.optString("to","");if(!OPS.contains(op)||!m.groups.contains(who))throw new IllegalArgumentException("Operación o parámetro no admitido.");boolean pair=op.equals("besa")||op.equals("mira")||op.equals("acercaactor");if(pair&&(!m.groups.contains(to)||who.equals(to))||!pair&&!to.isEmpty())throw new IllegalArgumentException("Destinatario inválido para "+op);}
 m.tests=row.getJSONArray("tests");if(m.tests.length()<1||m.tests.length()>3)throw new IllegalArgumentException("Cada módulo necesita entre una y tres pruebas.");for(int j=0;j<m.tests.length();j++){JSONObject test=m.tests.getJSONObject(j);keys(test,"input","actions");if(test.getString("input").length()>240)throw new IllegalArgumentException("Prueba demasiado larga.");JSONArray actions=test.getJSONArray("actions");if(actions.length()<1||actions.length()>24)throw new IllegalArgumentException("La prueba debe declarar las acciones esperadas.");for(int k=0;k<actions.length();k++)if(!Timeline.valid(actions.getString(k)))throw new IllegalArgumentException("Acción de prueba no admitida.");}modules.add(m);}}
 Match match(String input)throws Exception{String q=normalize(input);Match found=null;for(Module m:modules){Matcher matcher=m.compiled.matcher(q);if(!matcher.matches())continue;if(found!=null)throw new IllegalArgumentException("Más de un módulo interpreta el pedido. Ajustá sus patrones.");found=new Match();found.module=m;for(int i=0;i<m.groups.size();i++)found.values.put(m.groups.get(i),matcher.group(i+1).trim());}return found;}
 Result run(String input,SceneDraft base)throws Exception{Result out=new Result();Match match;try{match=match(input);}catch(IllegalArgumentException ambiguous){out.matched=true;out.module="patrones ambiguos";out.error=ambiguous.getMessage();return out;}if(match==null)return out;out.matched=true;out.module=match.module.id;if(base==null){out.error="Primero creá los personajes para este comportamiento.";return out;}SceneDraft d=base.copy();Map<String,SceneDraft.Actor> args=new HashMap<>();for(String key:match.values.keySet()){SceneDraft.Actor a=resolve(d,match.values.get(key));if(a==null){out.error="No identifiqué de forma única a «"+match.values.get(key)+"». Nombrá un personaje existente.";return out;}args.put(key,a);}if(args.containsKey("target")&&args.get("actor")==args.get("target")){out.error="Este comportamiento necesita dos personajes distintos.";return out;}
 int slot=d.actions.isEmpty()?0:ObjectTransfer.beats(d);for(int i=0;i<match.module.steps.length();i++){JSONObject step=match.module.steps.getJSONObject(i);String op=step.getString("op");SceneDraft.Actor a=args.get(step.getString("who")),to=args.get(step.optString("to",""));int needed=op.equals("besa")?2:1;if(slot+needed>SceneTiming.MAX_BEATS||d.actions.size()+(op.equals("besa")?3:1)>SceneTiming.MAX_ACTIONS){out.error="No queda tiempo en esta toma; prepará otra toma antes de aplicar el comportamiento.";return out;}if(op.equals("besa")){SceneDirector.step(d,a,"acercaactor",slot++,"",to.name);SceneDirector.step(d,a,"besa",slot,"",to.name);SceneDirector.step(d,to,"recibebeso",slot++,"",a.name);}else SceneDirector.step(d,a,op,slot++,"",to==null?"":to.name);d.focused=a.name;}
 try{SceneTiming.fit(d);SceneConsistency.require(d);String limit=BananaPixel.limitation(d);if(limit!=null)throw new IllegalArgumentException(limit);preserved(base,d);}catch(Exception invalid){out.error=invalid.getMessage();return out;}out.scene=d;return out;}
 static SceneDraft.Actor resolve(SceneDraft d,String value){String q=normalize(value).replaceFirst("^(?:el|la|un|una) ","");SceneDraft.Actor found=null;for(SceneDraft.Actor a:d.cast)if(q.equals(normalize(a.name))||q.equals(normalize(a.kind))||!a.label.isEmpty()&&q.equals(normalize(a.label))){if(found!=null&&found!=a)return null;found=a;}if(found!=null)return found;return SceneResolver.special(d,normalize(value));}
 static void preserved(SceneDraft before,SceneDraft after)throws Exception{if(before.cast.size()!=after.cast.size()||before.props.size()!=after.props.size())throw new IllegalArgumentException("Un módulo no puede cambiar el elenco u objetos.");for(SceneDraft.Actor a:before.cast){SceneDraft.Actor b=after.get(a.name);if(b==null||!a.designId.equals(b.designId)||!a.kind.equals(b.kind)||!a.label.equals(b.label)||!a.look.equals(b.look)||!a.reference.equals(b.reference)||a.size!=b.size||a.x!=b.x||a.y!=b.y||!a.voice.equals(b.voice)||!a.view.equals(b.view)||!a.relation.equals(b.relation)||a.behind!=b.behind)throw new IllegalArgumentException("El módulo alteró la identidad o el diseño de un personaje.");}for(int i=0;i<before.actions.size();i++)if(!before.actions.get(i).equals(after.actions.get(i))||!before.actors.get(i).equals(after.actors.get(i))||before.slot(i)!=after.slot(i)||!before.target(i).equals(after.target(i))||!before.recipient(i).equals(after.recipient(i)))throw new IllegalArgumentException("El módulo alteró la secuencia anterior.");for(SceneDraft.Prop a:before.props){SceneDraft.Prop b=after.prop(a.id);if(b==null||!a.holder.equals(b.holder)||a.x!=b.x||a.y!=b.y||!a.type.equals(b.type)||a.open!=b.open)throw new IllegalArgumentException("El módulo alteró un objeto.");}}
 static SceneDraft fixture(){SceneDraft d=new SceneDraft();SceneDraft.Actor a=new SceneDraft.Actor("zorro",26),b=new SceneDraft.Actor("banana",74);a.label="fito";b.label="bani";d.cast.add(a);d.cast.add(b);d.focused=a.name;SceneDirector.step(d,a,"espera",0,"","");return d;}
 String test()throws Exception{int total=0;for(Module m:modules)for(int i=0;i<m.tests.length();i++){JSONObject test=m.tests.getJSONObject(i);Result out=run(test.getString("input"),fixture());if(!out.matched||!out.module.equals(m.id)||out.scene==null)throw new IllegalArgumentException("Falló prueba de "+m.id+": "+(out.error.isEmpty()?"el patrón no identifica el módulo":out.error));JSONArray expected=test.getJSONArray("actions");List<String> actual=out.scene.actions.subList(1,out.scene.actions.size());if(actual.size()!=expected.length())throw new IllegalArgumentException("La prueba de "+m.id+" no coincide en cantidad de acciones.");for(int j=0;j<expected.length();j++)if(!actual.get(j).equals(expected.getString(j)))throw new IllegalArgumentException("La prueba de "+m.id+" no coincide en acción "+(j+1));total++;}return "Pruebas aprobadas: "+total+". El código pasó esquema, secuencia esperada, destinatarios, límites y conservación de diseños. No es una evaluación visual ni una prueba de todos los pedidos posibles.";}
}
